 for p in rs:
  for r in rs:
   if p['residual'] or not r['residual'] or p['activation'] not in ['relu','leaky_relu'] or r['activation'] not in ['relu','leaky_relu']:continue
   if p['depth']!=r['depth'] or p['depth']<3 or p['n_ln']>r['n_ln']:continue
   if any(p['optimizer'][k]!=r['optimizer'][k] for k in ['type','lr']):continue
   pairs.append((p,r))
for band in ['high','low','other']:
 ps=[(p,r) for p,r in pairs if (p['optimizer']['type'] in ['Adam','AdamW','RMSprop'] and p['dataset']['input_dim']>=8 and (p['optimizer']['lr']*p['budget']['training_steps']>=.05 if band=='high' else p['optimizer']['lr']*p['budget']['training_steps']<.05))] if band!='other' else pairs
 print(band,len(ps),sum(p['mean']<r['mean'] for p,r in ps),len(set(p['set_id'] for p,r in ps)))
 print([(p['dataset_id'],p['depth'],p['width'],r['width'],p['n_ln'],r['n_ln'],p['optimizer']['type'],p['optimizer']['lr'],round(p['mean']/r['mean'],3)) for p,r in ps][:25])"}

